xt')))) BETWEEN 1 AND 4000) OR JSON_TYPE(JSON_EXTRACT(e.body_json,'$.ordinary.body.resultReference'))='OBJECT') AND (e.version<>1 OR BINARY e.event_type='CREATE' OR JSON_CONTAINS_PATH(e.body_json,'one','$.baseline')=1) AND (JSON_CONTAINS_PATH(e.body_json,'one','$.baseline')=0 OR (JSON_LENGTH(JSON_EXTRACT(e.body_json,'$.baseline'))=16 AND JSON_EXTRACT(e.body_json,'$.baseline.id')=e.question_id AND JSON_EXTRACT(e.body_json,'$.baseline.patientId')=e.patient_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.kind'))='QUESTION' AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.id'))='INTEGER' AND JSON_EXTRACT(e.body_json,'$.baseline.id') BETWEEN 1 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.patientId'))='INTEGER' AND JSON_EXTRACT(e.body_json,'$.baseline.patientId') BETWEEN 1 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.userId'))='INTEGER' AND JSON_EXTRACT(e.body_json,'$.baseline.userId') BETWEEN 1 AND 9007199254740991 AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.kind'))='STRING' AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.title'))='STRING' AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.status'))='STRING' AND (JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.assignedUserId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.assignedUserId'))='INTEGER' AND JSON_EXTRACT(e.body_json,'$.baseline.assignedUserId') BETWEEN 1 AND 9007199254740991)) AND (JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.actorId'))='NULL' OR (JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.actorId'))='INTEGER' AND JSON_EXTRACT(e.body_json,'$.baseline.actorId') BETWEEN 1 AND 9007199254740991)) AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.actorName')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.eventAt')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.notifyAt')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.notifiedAt')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.escalatedAt')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.dataJson')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.createdAt')) IN ('STRING','NULL') AND JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.updatedAt')) IN ('STRING','NULL') AND CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.id'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.id'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.patientId'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.patientId'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.userId'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.userId'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.kind'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.kind'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.title'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.title'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.status'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.status'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.assignedUserId'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.assignedUserId'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.actorId'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.actorId'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.actorName'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.actorName'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.eventAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.eventAt'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.notifyAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.notifyAt'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.notifiedAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.notifiedAt'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.escalatedAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.escalatedAt'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.dataJson'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.dataJson'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.createdAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.createdAt'))) END+CASE WHEN JSON_TYPE(JSON_EXTRACT(e.body_json,'$.baseline.updatedAt'))='NULL' THEN 0 ELSE OCTET_LENGTH(JSON_UNQUOTE(JSON_EXTRACT(e.body_json,'$.baseline.updatedAt'))) END<=131072))),0)<>1 END)
  AND NOT EXISTS(SELECT 1 FROM visit_question_command c WHERE COALESCE((c.id BETWEEN 1 AND 9007199254740991 AND c.actor_id BETWEEN 1 AND 9007199254740991
