  AND NOT EXISTS(SELECT 1 FROM visit_question_command c WHERE c.question_id IS NULL OR c.result_json IS NULL OR JSON_VALID(c.result_json)<>1)
  AND NOT EXISTS(SELECT 1 FROM visit_question_command c WHERE CASE WHEN c.result_json IS NULL OR JSON_VALID(c.result_json)<>1 THEN 1 WHEN JSON_TYPE(c.result_json)<>'OBJECT' OR JSON_LENGTH(c.result_json)<>4 OR OCTET_LENGTH(c.result_json)>512 THEN 1 ELSE NOT EXISTS(SELECT 1 FROM visit_question_event e JOIN visit_question_state s ON s.question_id=e.question_id AND s.patient_id=e.patient_id WHERE e.question_id=c.question_id AND e.actor_id=c.actor_id AND e.version=c.expected_version+1 AND JSON_TYPE(JSON_EXTRACT(c.result_json,'$.questionId'))='INTEGER' AND JSON_EXTRACT(c.result_json,'$.questionId') BETWEEN 1 AND 9007199254740991 AND JSON_EXTRACT(c.result_json,'$.questionId')=e.question_id AND JSON_TYPE(JSON_EXTRACT(c.result_json,'$.version'))='INTEGER' AND JSON_EXTRACT(c.result_json,'$.version') BETWEEN 1 AND 9007199254740991 AND JSON_EXTRACT(c.result_json,'$.version')=e.version AND JSON_TYPE(JSON_EXTRACT(c.result_json,'$.eventId'))='INTEGER' AND JSON_EXTRACT(c.result_json,'$.eventId') BETWEEN 1 AND 9007199254740991 AND JSON_EXTRACT(c.result_json,'$.eventId')=e.id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.result_json,'$.state'))=e.to_state) END)
  AND NOT EXISTS(SELECT 1 FROM visit_question_event e WHERE (SELECT COUNT(*) FROM visit_question_command c WHERE c.question_id=e.question_id AND c.expected_version=e.version-1 AND c.actor_id=e.actor_id AND c.result_json IS NOT NULL)=0)
THEN 1 ELSE 0 END AS coherent;
-- 最后一项 coherent 必须为 1；任何未知、错误或 0 均为 STOP，不启用功能。
